package org.localscape.nylocas.ranger;
import org.junit.Test;import org.localscape.nylocas.ranger.RangerStrategy.*;import static org.junit.Assert.*;
public class RangerFirstAdmissionParentHoldTest {
 private Crab south,west;
 private Crab add(Room r,int key,int born,int wave,Lane lane,boolean big,Style style,int x,int y){Crab c=new Crab(key,key,born,wave,lane,'S',big,style,RangerStrategy.tile(x,y));c.pendingDamage=0;r.crabs.add(c);return c;}
 private Room room(){Room r=new Room();r.wave=19;r.spawns[18]=144;r.spawns[19]=152;r.ready=158;r.player=RangerStrategy.tile(3291,4246);for(int i=0;i<3;i++)add(r,80+i,128,17,Lane.values()[i],true,Style.MELEE,3299,4251);add(r,72,112,15,Lane.SOUTH,true,Style.MAGIC,3292,4244);west=add(r,87,144,18,Lane.WEST,true,Style.RANGE,3288,4248);west.hp=0;west.dying=true;south=add(r,88,144,18,Lane.SOUTH,true,Style.RANGE,3293,4243);add(r,89,144,18,Lane.EAST,true,Style.RANGE,3295,4253);for(int i=0;i<3;i++)add(r,90+i,152,19,Lane.values()[i],true,Style.MELEE,3295,4240);return r;}
 @Test public void nativeTenBodiesAndWestCorpseDelayTheNewParentExactlyOneReadyTick(){Room r=room();Decision d=new RangerStrategy().decide(r,158);assertNull(d.reason,d.target);assertEquals("Protect first20 cap: defer new18 parent one tick",d.reason);assertEquals(r.player,d.tile);}
 @Test public void releaseAtTheVeryNextTickEvenIfTheCorpseRemains(){Room r=room();RangerStrategy s=new RangerStrategy();s.decide(r,158);r.ready=159;assertSame(south,s.decide(r,159).target);}
 @Test public void noEarlierOrLaterOrAfterAdmissionHold(){for(int tick:new int[]{157,159}){Room r=room();r.ready=tick;assertNotEquals("Protect first20 cap: defer new18 parent one tick",new RangerStrategy().decide(r,tick).reason);}Room r=room();r.wave=20;r.spawns[20]=158;assertSame(south,new RangerStrategy().decide(r,158).target);}
 @Test public void aRealParentSurvivorAndKnownPendingRollReleaseImmediately(){Room r=room();RangerStrategy s=new RangerStrategy();s.attacked(new Decision(south,Weapon.PIPE,r.player,false,null,"actual"),156);south.hp=3;assertSame(south,s.decide(r,158).target);r=room();south.pendingDamage=5;assertSame(south,new RangerStrategy().decide(r,158).target);}
 @Test public void injuredUnopenedParentAlsoKeepsItsExistingService(){Room r=room();south.hp=7;assertSame(south,new RangerStrategy().decide(r,158).target);}
 @Test public void anyLiveAvailableSmallDisablesTheNewHold(){Room r=room();r.crabs.remove(0);add(r,93,154,19,Lane.SPLIT,false,Style.RANGE,3292,4246);Decision d=new RangerStrategy().decide(r,158);assertNotEquals("Protect first20 cap: defer new18 parent one tick",d.reason);}
 @Test public void aLiveWestOrLowerPopulationHasNoForecastHold(){Room r=room();west.hp=16;west.dying=false;assertNotEquals("Protect first20 cap: defer new18 parent one tick",new RangerStrategy().decide(r,158).reason);r=room();r.crabs.remove(0);assertSame(south,new RangerStrategy().decide(r,158).target);}
 @Test public void anOriginalNineteenMagicPacketIsNeverTheDeferredAction(){Room r=room();r.spawns[19]=155;r.ready=158;Crab packet=r.crabs.get(7);packet.style=Style.MAGIC;packet.point=RangerStrategy.tile(3284,4248);assertNotEquals("Protect first20 cap: defer new18 parent one tick",new RangerStrategy().decide(r,158).reason);}
}